def order(id: String): Behavior[Command] = Behaviors.setup { ctx =>
  EventSourcedBehavior[Command, Event, State](
    persistenceId = PersistenceId.ofUniqueId(id),
    emptyState = State.AwaitingPayment,
    commandHandler = (state, cmd) => state match {
      case State.AwaitingPayment => cmd match {
        case PaymentOk(_)   => Effect.persist(Paid).thenReply(ctx)(_ => Ack)
        case TimeoutFired   => Effect.persist(TimedOut).thenRun(_ => releaseCredit(id))
      }
      case _ => Effect.none
    },
    eventHandler = applyEvent)
  .withTagger(_ => Set("orders"))
}
